function formatWorkMarketDate(value) {
    const date = new Date(value);
    const month = String(date.getMonth() + 1).padStart(2, "0");
    const day = String(date.getDate()).padStart(2, "0");
    const year = date.getFullYear();
    return `${month}/${day}/${year}`;
}
function formatWorkMarketTime(value) {
    return new Intl.DateTimeFormat("en-US", {
        hour: "numeric",
        minute: "2-digit",
        hour12: true,
        timeZone: "America/New_York"
    })
        .format(new Date(value))
        .replace(/\s/g, "");
}
function deriveHourlyRate(job, decision) {
    if (decision.counterOffer?.hourlyRate) {
        return decision.counterOffer.hourlyRate;
    }
    if (job.compensation.hourlyRate) {
        return job.compensation.hourlyRate;
    }
    const estimatedHours = job.compensation.estimatedHours ?? job.requestedWindow.durationHours;
    return Math.round((job.compensation.totalBudget / estimatedHours) * 100) / 100;
}
export function buildWorkMarketRequest(job, decision) {
    const workOrderId = job.platformWorkOrderId ?? job.id.replace(/^wm:/, "");
    if (!decision.executionPlan) {
        throw new Error("Decision is missing execution plan");
    }
    if (decision.executionPlan.action === "apply") {
        return {
            platform: "WorkMarket",
            action: "apply",
            method: "POST",
            path: `/assignments/apply/${workOrderId}`,
            contentType: "application/x-www-form-urlencoded",
            body: {
                _tk: "<csrf-token>",
                note: "",
                tieredPricingAccepted: false,
                isform: true
            },
            auth: {
                requiresCookies: true,
                requiresCsrfToken: true
            }
        };
    }
    if (decision.executionPlan.action === "counter") {
        const hours = job.compensation.estimatedHours ?? job.requestedWindow.durationHours;
        const counterStart = decision.counterOffer?.counterStart;
        const body = {
            _tk: "<csrf-token>",
            is_internal_pricing: "false",
            has_tiered_pricing: "false",
            priceType: "2",
            price_negotiation: "on",
            pricing: "2",
            per_hour_price: deriveHourlyRate(job, decision),
            max_number_of_hours: hours,
            additional_expenses: decision.counterOffer?.travelExpense ?? 0,
            note: decision.counterOffer?.note ?? "Counter offer generated by FieldOps v2",
            isform: "true",
            submit: ""
        };
        if (counterStart) {
            body.schedule_negotiation = "on";
            body.reschedule_option = "time";
            body.from = formatWorkMarketDate(counterStart);
            body.fromtime = formatWorkMarketTime(counterStart);
        }
        return {
            platform: "WorkMarket",
            action: "counter",
            method: "POST",
            path: `/assignments/negotiate/${workOrderId}`,
            contentType: "application/x-www-form-urlencoded",
            body,
            auth: {
                requiresCookies: true,
                requiresCsrfToken: true
            }
        };
    }
    throw new Error(`Unsupported WorkMarket execution action: ${decision.executionPlan.action}`);
}
